def col(x,items,title):
    s=lab(x+70,22,title,13.5,800);y=34
    for t,h,c in items: s+=f'<rect x="{x}" y="{y}" width="140" height="{h-4}" rx="8" fill="{c}" opacity=".18"/>'+lab(x+70,y+h/2+3,t,12.5,800);y+=h
    return s
